import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return history[-1][1]
    if n == 3:
        opp = [a for _, a in history]
        if opp.count('D') >= 2:
            return 'D'
        return 'C'
    if n == 4:
        opp = [a for _, a in history]
        return 'D' if opp.count('D') >= 2 else 'C'
    opp = [a for _, a in history]
    mine = [a for a, _ in history]
    last_opp = opp[-1]
    last_mine = mine[-1]
    opp_def = opp.count('D')
    my_def = mine.count('D')
    tail = opp[-12:]
    tail_def = tail.count('D')
    recent = opp[-6:]
    recent_def = recent.count('D')
    if tail_def >= 8:
        return 'D'
    if recent_def >= 4:
        return 'D'
    if opp_def >= 20 and n >= 20:
        if tail_def >= 5:
            return 'D'
    if opp_def >= 35 and n >= 40:
        return 'D'
    if n >= 10:
        last4 = opp[-4:]
        if last4 == ['D', 'C', 'D', 'C']:
            return 'D'
        if last4 == ['C', 'D', 'C', 'D']:
            return 'D'
    if n >= 6:
        if opp[-1] == 'D' and opp[-2] == 'D' and opp[-3] == 'D':
            return 'D'
    if n >= 3:
        if opp[-1] == 'D' and opp[-2] == 'D':
            r = rng.random()
            if r < 0.7:
                return 'D'
    if n >= 2:
        if opp[-1] == 'D':
            r = rng.random()
            if r < 0.25:
                return 'D'
    if n >= 20 and opp_def * 3 < n:
        pass
    if n >= 30:
        if tail_def == 0 and recent_def == 0:
            return 'C'
    if n >= 50:
        if tail_def <= 1:
            return 'C'
    if n >= 4:
        if opp[-1] == 'C' and opp[-2] == 'C':
            return 'C'
    if n >= 8:
        r = rng.random()
        if r < 0.03:
            return 'D'
    return 'C'

